void evalFieldInit(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  struct twostream_ctx *app = ctx;
  double x = xn[0];

  double alpha = app->alpha;
  double kx = app->kx;

  double Ex = -alpha * sin(kx * x) / kx; // Total electric field (x-direction).
  double Ey = 0.0; // Total electric field (y-direction).
  double Ez = 0.0; // Total electric field (z-direction).

  double Bx = 0.0; // Total magnetic field (x-direction).
  double By = 0.0; // Total magnetic field (y-direction).
  double Bz = 0.0; // Total magnetic field (z-direction).

  // Set electric field.
  fout[0] = Ex;
  fout[1] = Ey, fout[2] = Ez;
  // Set magnetic field.
  fout[3] = Bx;
  fout[4] = By;
  fout[5] = Bz;
  // Set correction potentials.
  fout[6] = 0.0;
  fout[7] = 0.0;
}

