       .c2p_ctx = &ctx,
       .bfield_func = bfield_func,
       .bfield_ctx = &ctx},

    .num_periodic_dir = 1,
    .periodic_dirs = {0},

    .num_species = 2,
    .species = {elc, ion},

    .field = field,

    .parallelism = {.use_gpu = app_args.use_gpu, .cuts = {app_args.cuts[0]}, .comm = comm}
